def reach(n,T,omega,u,mut):
    # vertices (i,l); return set reachable from (u,0); reflexive except mutant nonreflexive
    on={t for t,b in zip(T,omega) if b}
    adj={}
    def add(a,b): adj.setdefault(a,[]).append(b)
    for t in on:
        if t[0]=="h":
            _,i,j,l=t
            ls=[0,1] if mut=="coupled_h" else [l]
            for l2 in ls:
                add((i,l2),(j,l2))
                if mut=="undirected_h": add((j,l2),(i,l2))
        else:
            i=t[1]
            if mut=="two_vertical":
                add((i,t[2]),(i,1-t[2]))
            elif mut=="oneway_vertical":
                add((i,0),(i,1))
            else:
                add((i,0),(i,1));add((i,1),(i,0))
    start=(u,0)
    seen=set()
    stack=[start] if mut!="nonreflexive" else list(adj.get(start,[]))
    if mut!="nonreflexive": seen.add(start)
    else:
        seen=set(stack)
    while stack:
        x=stack.pop()
        for y in adj.get(x,[]):
            if y not in seen: seen.add(y); stack.append(y)
    return seen
