    tok=lambda j: sum(2*k+1 for k in range(0,j))+1  # 1 vertical at index 0 + sum_{k=1..j}(2k+1) ... computed below
    def win_tokens(j):
        # tmax<=j tokens: for each index k<=j: vertical(1) + horizontal into k: 2k
        return sum(1+2*k for k in range(j+1))
    st=defaultdict(int)
    # state at u: only the vertical token of u matters among window tokens; others free
    free=win_tokens(u)-1
    st[(1,1)]=1<<free; st[(1,0)]=1<<free
    results[u]=dict(st)
    tcount={u:(1<<free, 2<<free)}  # (true-layer count, false-layer count) for v=u: true reachable if vertical on (1 way) ; false always
    for j in range(u,n-1):
        new=defaultdict(int)
        hit_t,hit_f=0,0
        # fresh tokens: j+1 horizontals into j+1 per layer (j+1 of them each) + 1 vertical
        for (a,b),c in st.items():
            ra=[(0,1<<(j+1-a)),(1,(1<<(j+1))-(1<<(j+1-a)))]
            rb=[(0,1<<(j+1-b)),(1,(1<<(j+1))-(1<<(j+1-b)))]
            for x,wx in ra:
                for y,wy in rb:
                    for z in (0,1):
