                        B=(x or y) if z else y
                        new[(a+A,b+B)]+=c*wx*wy
                        if B: hit_t+=c*wx*wy
                        if A: hit_f+=c*wx*wy
        st=new
        results[j+1]=dict(st)
        tcount[j+1]=(hit_t,hit_f)
    return tcount
